
.bb-card {
  width: 100%;
  max-width: 640px;
  background: var(--bb-bg-deep);
  border: 1px solid var(--bb-border);
  border-radius: 8px;
  box-shadow: 0 0 20px rgba(249, 132, 38, 0.06);
  font-family: var(--font-main);
  color: var(--bb-text);
  font-size: 13px;
  line-height: 1.5;
  margin: 0 auto;
  position: relative;
  overflow: hidden;
}

.court-line {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--bb-orange), var(--bb-gold), var(--bb-orange), transparent);
  opacity: 0.8;
}

.world-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 12px 14px 10px;
  border-bottom: 1px solid var(--bb-border);
  font-size: 12px;
}

.world-item {
  color: var(--bb-text-dim);
}

.world-item b {
  color: var(--bb-orange);
  font-weight: 600;
}

.hero-section,
.character-card {
  background: var(--bb-bg-panel);
  border: 1px solid var(--bb-border);
  border-radius: 8px;
}

.hero-section {
  margin: 12px 14px;
  padding: 10px;
}

.hero-header,
.character-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.hero-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--bb-text-bright);
}

.hero-caption {
  font-size: 11px;
  color: var(--bb-text-dim);
}

.hero-tag,
.character-tag,
.panel-meta {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--bb-orange-dim);
  color: var(--bb-orange);
  white-space: nowrap;
}

.simple-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}

.info-card {
  min-width: 0;
  padding: 8px;
  border-radius: 8px;
  background: rgba(28, 35, 51, 0.9);
  border: 1px solid rgba(249, 132, 38, 0.08);
}

.info-card-wide {
  grid-column: span 2;
}

.metric-text {
  color: var(--bb-text-bright);
  font-weight: 600;
}

.metric-label,
.section-mini-title {
  display: block;
  margin-bottom: 4px;
  color: var(--bb-text-dim);
  font-size: 11px;
  letter-spacing: 0.02em;
}

.task-block {
  margin-top: 10px;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.task-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 8px;
  border-radius: 6px;
  background: rgba(13, 17, 23, 0.65);
}

.task-name,
.character-name {
  color: var(--bb-text-bright);
  font-weight: 600;
}

.task-desc,
.character-status {
  font-size: 11px;
  color: var(--bb-text-dim);
}

.character-relation {
  color: var(--bb-orange);
  font-size: 12px;
  margin-top: 6px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 14px;
  background: var(--bb-bg-panel);
  cursor: pointer;
  user-select: none;
  font-size: 13px;
  font-weight: 600;
  color: var(--bb-text-bright);
  border-top: 1px solid rgba(249, 132, 38, 0.04);
  border-bottom: 1px solid var(--bb-border);
}

.panel-header:hover {
  background: var(--bb-bg-card);
}

.panel-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.toggle {
  font-size: 10px;
  color: var(--bb-text-dim);
}

.characters-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  padding: 10px 14px 14px;
}

.character-card {
  padding: 9px;
}

@media (max-width: 720px) {
  .characters-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .simple-grid {
    grid-template-columns: 1fr;
  }

  .info-card-wide {
    grid-column: span 1;
  }

  .world-bar {
    gap: 8px;
  }
}
